import React, { useMemo, useState } from "react";
import api from "../services/api.ts";
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  BarElement,
  Title,
  Tooltip,
  Legend,
  Filler,
} from "chart.js";
import { Line, Bar } from "react-chartjs-2";
import { useClub } from "../hooks/useClub.tsx";
import { PageHeader, PageShell } from "../components/ui.tsx";
import { useClubIds } from "../hooks/useClubIds.ts";
import { useAbortableFetch } from "../hooks/useAbortableFetch.ts";
import { API_ENDPOINTS } from "../config/urls.ts";
import { useTheme } from "../hooks/useTheme.tsx";
import { chartTheme, cssVar, seriesColor } from "../utils/themeColors.ts";
import { RatingPill } from "../components/ui.tsx";
import { fmtDateBRShort } from "../utils/date.ts";
import { withAlpha, movingAvg } from "../utils/chart.ts";

ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, BarElement, Title, Tooltip, Legend, Filler);

// =========================
// Types
// =========================

type Result = "W" | "D" | "L";

interface MatchTrendPointDto {
  matchId: number;
  timestamp: string;
  opponentClubId: number;
  opponentName: string;
  goalsFor: number;
  goalsAgainst: number;
  result: Result | string;
  shots: number;
  passesMade: number;
  passAttempts: number;
  passAccuracyPercent: number;
  tacklesMade: number;
  tackleAttempts: number;
  tackleSuccessPercent: number;
  avgRating: number;
  momOccurred: boolean;
}

interface ClubTrendsDto {
  clubId: number;
  clubName: string;
  series: MatchTrendPointDto[];
  formLast5: string;
  formLast10: string;
  currentUnbeaten: number;
  currentWins: number;
  currentCleanSheets: number;
  movingAvgPassAcc_5: number[];
  movingAvgRating_5: number[];
  movingAvgTackleAcc_5: number[];
}

interface TopItemDto {
  playerEntityId: number;
  playerId: number;
  playerName: string;
  clubId: number;
  goals: number;
  assists: number;
  preAssists: number;
  matches: number;
  avgRating: number;
  mom: number;
}

// =========================
// Helpers
// =========================

const pillColor = (r: Result) => (r === "W" ? "bg-positive" : r === "D" ? "bg-warning" : "bg-negative");

function FormPills({ form }: { form: string }) {
  if (!form) return <span className="text-fg-subtle">—</span>;
  return (
    <div className="flex flex-wrap gap-1">
      {form.split("").filter((ch) => ch === "W" || ch === "D" || ch === "L").map((ch, i) => {
        const cls =
          ch === "W"
            ? "bg-positive-soft text-positive-fg border-positive/40"
            : ch === "D"
            ? "bg-warning-soft text-warning-fg border-warning/40"
            : "bg-negative-soft text-negative-fg border-negative/40";
        return (
          <span
            key={i}
            className={`inline-flex items-center justify-center w-5 h-5 rounded text-[11px] font-bold border ${cls}`}
          >
            {ch}
          </span>
        );
      })}
    </div>
  );
}

// =========================
// Component
// =========================

export default function TrendsPage() {
  const { selectedClubs } = useClub();
  const { resolvedTheme } = useTheme();

  // ids efetivos (multi). Se nenhum selecionado, tenta o single legacy.
  const idsToUse = useClubIds();

  const [last, setLast] = useState(20);
  const [reloadNonce, setReloadNonce] = useState<number>(0);

  // mapas por clube
  const [trendsByClub, setTrendsByClub] = useState<Record<number, ClubTrendsDto>>({});
  const [topsByClub, setTopsByClub] = useState<Record<number, TopItemDto[]>>({});

  // UI state
  type Metric = "pass" | "tackle" | "rating" | "gfga" | "gdiff";
  const [metric, setMetric] = useState<Metric>("pass");
  type ChartKind = "line" | "area" | "bar";
  const [chartKind, setChartKind] = useState<ChartKind>("line");
  const [smooth, setSmooth] = useState(true);
  type XMode = "index" | "date";
  const [xMode, setXMode] = useState<XMode>("index"); // se multi, força "index" abaixo

  // -------- Fetch (multi) --------
  const { loading, error } = useAbortableFetch(
    async (signal) => {
      const trendPromises = idsToUse.map((id) =>
        api.get<ClubTrendsDto>(API_ENDPOINTS.TRENDS_CLUB(id, last), { signal })
      );
      const topsPromises = idsToUse.map((id) =>
        api.get<TopItemDto[]>(API_ENDPOINTS.TRENDS_TOP_SCORERS(id, 10, last), { signal })
      );

      const [trendResArr, topsResArr] = await Promise.all([Promise.all(trendPromises), Promise.all(topsPromises)]);

      if (signal.aborted) return;

      const tMap: Record<number, ClubTrendsDto> = {};
      const pMap: Record<number, TopItemDto[]> = {};

      trendResArr.forEach((r) => (tMap[r.data.clubId] = r.data));
      topsResArr.forEach((r, idx) => (pMap[idsToUse[idx]] = r.data));

      setTrendsByClub(tMap);
      setTopsByClub(pMap);
    },
    [idsToUse.join(","), last, reloadNonce], // join para mudar quando a lista mudar
    { enabled: idsToUse.length > 0, errorMessage: "Erro ao carregar tendências" }
  );

  // -------- Derived (multi) --------
  const clubsWithData = useMemo(
    () => idsToUse.map((id) => trendsByClub[id]).filter((x): x is ClubTrendsDto => !!x),
    [idsToUse, trendsByClub]
  );

  const singleClub = clubsWithData.length === 1 ? clubsWithData[0] : null;

  // Cor da linha/destaque de cada clube: tokens do tema (1º clube = accent), não um hash do id
  const clubHex = (clubId: number) => seriesColor(Math.max(0, clubsWithData.findIndex((x) => x.clubId === clubId)));


  // X labels: se multi, força índice; se single, respeita xMode
  const effectiveXMode: XMode = clubsWithData.length > 1 ? "index" : xMode;

  // comprimento máximo para label de índice
  const maxLen = useMemo(() => {
    let m = 0;
    for (const c of clubsWithData) m = Math.max(m, c.series.length);
    return m;
  }, [clubsWithData]);

  const xIndexLabels = useMemo(() => Array.from({ length: maxLen }, (_, i) => `Jogo ${i + 1}`), [maxLen]);

  const xDateLabels = useMemo(() => {
    if (!singleClub) return xIndexLabels; // fallback em multi
    return singleClub.series.map((p) => fmtDateBRShort(p.timestamp));
  }, [singleClub, xIndexLabels]);

  const xLabels = effectiveXMode === "index" ? xIndexLabels : xDateLabels;

  // ponto pequeno quando há muitos jogos (considera máximo)
  const manyPoints = maxLen > 25;
  const pointRadius = manyPoints ? 0 : 2;

  // construir datasets por métrica
  const chartData = useMemo(() => {
    // helper para pegar valores + smoothing
    const valuesFor = (series: MatchTrendPointDto[], kind: Metric) => {
      if (kind === "pass") return series.map((s) => s.passAccuracyPercent ?? 0);
      if (kind === "tackle") return series.map((s) => s.tackleSuccessPercent ?? 0);
      if (kind === "rating") return series.map((s) => s.avgRating ?? 0);
      if (kind === "gfga")
        return { gf: series.map((s) => s.goalsFor ?? 0), ga: series.map((s) => s.goalsAgainst ?? 0) };
      if (kind === "gdiff") return series.map((s) => (s.goalsFor ?? 0) - (s.goalsAgainst ?? 0));
      return [];
    };

    // métricas simples (uma linha por clube)
    if (metric === "pass" || metric === "tackle" || metric === "rating") {
      const datasets = clubsWithData.map((c) => {
        const baseVals = valuesFor(c.series, metric) as number[];
        const vals = smooth ? movingAvg(baseVals, 5) : baseVals;
        const hex = clubHex(c.clubId);
        return {
          type: chartKind === "bar" ? "bar" : "line",
          label: c.clubName,
          data: vals,
          borderColor: hex,
          backgroundColor: chartKind === "bar" ? withAlpha(hex, 0.25) : withAlpha(hex, 0.15),
          borderWidth: 2,
          tension: 0.3,
          pointRadius,
          fill: chartKind === "area",
        } as const;
      });

      // pad datasets para mesmo length (Chart.js aceita; valores faltantes como null)
      const padded = datasets.map((ds) => ({
        ...ds,
        data: [...ds.data, ...Array(Math.max(0, maxLen - ds.data.length)).fill(null)],
      }));

      return { labels: xLabels, datasets: padded as any[] };
    }

    // gfga: duas séries por clube (GF e GA)
    if (metric === "gfga") {
      const datasets: any[] = [];
      for (const c of clubsWithData) {
        const base = valuesFor(c.series, "gfga") as { gf: number[]; ga: number[] };
        const gfVals = smooth ? movingAvg(base.gf, 5) : base.gf;
        const gaVals = smooth ? movingAvg(base.ga, 5) : base.ga;
        const hex = clubHex(c.clubId);

        datasets.push({
          type: chartKind === "bar" ? "bar" : "line",
          label: `${c.clubName} — Gols feitos`,
          data: [...gfVals, ...Array(Math.max(0, maxLen - gfVals.length)).fill(null)],
          borderColor: hex,
          backgroundColor: chartKind === "bar" ? withAlpha(hex, 0.35) : withAlpha(hex, 0.18),
          borderWidth: 2,
          tension: 0.3,
          pointRadius,
          fill: chartKind === "area",
        });
        datasets.push({
          type: chartKind === "bar" ? "bar" : "line",
          label: `${c.clubName} — Gols levados`,
          data: [...gaVals, ...Array(Math.max(0, maxLen - gaVals.length)).fill(null)],
          borderColor: withAlpha(hex, 0.7),
          backgroundColor: chartKind === "bar" ? withAlpha(hex, 0.22) : withAlpha(hex, 0.12),
          borderDash: [6, 3],
          borderWidth: 2,
          tension: 0.3,
          pointRadius,
          fill: chartKind === "area",
        });
      }
      return { labels: xLabels, datasets };
    }

    // gdiff: uma série por clube (barras positivas/negativas ficam com cor via callback)
    if (metric === "gdiff") {
      const datasets = clubsWithData.map((c) => {
        const base = valuesFor(c.series, "gdiff") as number[];
        const vals = smooth ? movingAvg(base, 5) : base;
        const hex = clubHex(c.clubId);
        const negFill = cssVar("--color-negative", 0.45);
        const fillColor =
          chartKind === "bar"
            ? (ctx: any) => ((ctx.raw ?? 0) >= 0 ? withAlpha(hex, 0.45) : negFill)
            : withAlpha(hex, 0.2);

        return {
          type: chartKind === "bar" ? "bar" : "line",
          label: `${c.clubName} — Dif. de gols`,
          data: [...vals, ...Array(Math.max(0, maxLen - vals.length)).fill(null)],
          borderColor: hex,
          backgroundColor: fillColor as any,
          borderWidth: 2,
          tension: 0.3,
          pointRadius,
          fill: chartKind === "area",
        } as any;
      });
      return { labels: xLabels, datasets };
    }

    return { labels: xLabels, datasets: [] };
  }, [clubsWithData, metric, chartKind, smooth, xLabels, maxLen, pointRadius, resolvedTheme]);

  // opções de eixo/tooltip mais limpas
  const baseOptions: any = useMemo(
    () => {
    const t = chartTheme();
    return {
      responsive: true,
      maintainAspectRatio: false,
      animation: false,
      interaction: { mode: "index", intersect: false },
      plugins: {
        legend: { display: true, position: "top", labels: { color: t.fg } },
        tooltip: {
          backgroundColor: t.surface,
          titleColor: t.fg,
          bodyColor: t.fg,
          borderColor: t.border,
          borderWidth: 1,
          callbacks: {
            title: (items: any[]) => {
              if (!items?.length) return "";
              const i = items[0].dataIndex ?? 0;

              if (effectiveXMode === "index") {
                return `Jogo ${i + 1}`;
              }

              // single-club + por data
              const s = singleClub?.series?.[i];
              if (!s) return items?.[0]?.label ?? "";
              const date = fmtDateBRShort(s.timestamp);
              const vs = s.opponentName ? ` vs ${s.opponentName}` : "";
              const placar = ` • ${s.goalsFor}-${s.goalsAgainst}`;
              return `${date}${vs}${placar}`;
            },
            label: (ctx: any) => {
              const v = ctx.raw as number;
              const isRating = metric === "rating";
              return `${ctx.dataset.label}: ${Number.isFinite(v) ? v.toFixed(isRating ? 2 : 1) : "-"}`;
            },
          },
        },
      },
      scales: {
        x: {
          grid: { display: false, color: t.grid },
          ticks: { autoSkip: true, maxTicksLimit: 8, color: t.fgMuted },
        },
        y: {
          beginAtZero: true,
          grid: { color: t.grid },
          ticks: { callback: (v: any) => `${v}`, color: t.fgMuted },
        },
      },
      elements: {
        point: { radius: pointRadius },
        line: { borderJoinStyle: "round", borderCapStyle: "round" },
      },
    };
    },
    [effectiveXMode, singleClub?.series, pointRadius, metric, resolvedTheme]
  );

  const ChartComponent =
    metric === "gfga" || metric === "gdiff" ? (chartKind === "bar" ? Bar : Line) : chartKind === "bar" ? Bar : Line;

  const quickLasts = [5, 10, 20, 50];
  const forceReload = () => setReloadNonce(Date.now());

  const clubNamesLabel =
    idsToUse.length > 0 ? (
      <>
        Clubes ativos:{" "}
        <span className="font-medium">
          {idsToUse.map((id) => selectedClubs.find((c) => c.clubId === id)?.clubName ?? trendsByClub[id]?.clubName ?? `Clube ${id}`).join(", ")}
        </span>
      </>
    ) : undefined;

  // =========================
  // Render
  // =========================

  return (
    <PageShell size="2xl" className="space-y-6">
      <PageHeader
        eyebrow="Clube"
        title="Tendências e sequências"
        subtitle={clubNamesLabel}
        className="mb-0"
        actions={
          <>
          <span className="text-sm text-fg-secondary">Últimos</span>
          <div className="flex items-center gap-1">
            {quickLasts.map((n) => (
              <button
                key={n}
                onClick={() => setLast(n)}
                className={`text-sm px-2.5 py-1 rounded-lg border shadow-sm transition-colors ${
                  last === n ? "bg-accent text-accent-fg border-accent" : "bg-surface text-fg-secondary hover:bg-surface-raised"
                }`}
                aria-pressed={last === n}
              >
                {n}
              </button>
            ))}
          </div>
          <input
            type="number"
            className="border rounded px-2 py-1 w-24"
            min={5}
            value={last}
            onChange={(e) => setLast(Math.max(5, parseInt(e.target.value) || 5))}
          />
          <span className="text-sm text-fg-secondary">jogos</span>
          <button
            onClick={forceReload}
            className="ml-2 text-sm px-3 py-1 rounded border bg-surface hover:bg-surface-raised"
            title="Recarregar"
          >
            Recarregar
          </button>
          </>
        }
      />

      {idsToUse.length === 0 && (
        <div className="p-3 bg-warning-soft border border-warning/40 text-warning-fg rounded">
          Selecione um clube no menu para ver as tendências.
        </div>
      )}

      {idsToUse.length > 0 && loading && (
        <div className="grid gap-3">
          <div className="animate-pulse bg-surface border rounded-xl p-4 h-20" />
          <div className="animate-pulse bg-surface border rounded-xl p-4 h-24" />
          <div className="animate-pulse bg-surface border rounded-xl p-4 h-[340px]" />
          <div className="animate-pulse bg-surface border rounded-xl p-4 h-48" />
        </div>
      )}

      {idsToUse.length > 0 && error && (
        <div className="p-3 bg-negative-soft border border-negative/40 text-negative-fg rounded flex items-center justify-between">
          <span>{error}</span>
          <button onClick={forceReload} className="text-sm px-3 py-1 rounded border bg-surface hover:bg-surface-raised">
            Tentar novamente
          </button>
        </div>
      )}

      {idsToUse.length > 0 && !loading && !error && clubsWithData.length > 0 && (
        <>
          {/* Cards - forma e streaks por clube */}
          <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-3">
            {clubsWithData.map((c) => (
              <div
                key={c.clubId}
                className="bg-surface border border-l-4 rounded-xl p-4"
                style={{ borderLeftColor: clubHex(c.clubId) }}
              >
                <div className="flex items-center justify-between mb-3">
                  <div className="text-base font-semibold">{c.clubName}</div>
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
                  <div>
                    <div className="text-xs text-fg-muted mb-1">Forma (Últimos 5)</div>
                    <FormPills form={c.formLast5} />
                  </div>
                  <div>
                    <div className="text-xs text-fg-muted mb-1">Forma (Últimos 10)</div>
                    <FormPills form={c.formLast10} />
                  </div>
                  <div className="grid grid-cols-3 text-center gap-2">
                    <div>
                      <div className="text-[11px] text-fg-muted">Sem perder</div>
                      <div className={`text-lg font-bold ${c.currentUnbeaten > 0 ? "text-positive" : "text-fg-subtle"}`}>
                        {c.currentUnbeaten}
                      </div>
                    </div>
                    <div>
                      <div className="text-[11px] text-fg-muted">Vitórias</div>
                      <div className={`text-lg font-bold ${c.currentWins > 0 ? "text-positive" : "text-fg-subtle"}`}>
                        {c.currentWins}
                      </div>
                    </div>
                    <div>
                      <div className="text-[11px] text-fg-muted">Clean sheets</div>
                      <div className={`text-lg font-bold ${c.currentCleanSheets > 0 ? "text-accent" : "text-fg-subtle"}`}>
                        {c.currentCleanSheets}
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            ))}
          </div>

          {/* CONTROLES DO GRÁFICO */}
          <div className="bg-surface border rounded-xl p-4">
            <div className="flex flex-wrap items-center gap-3 border-b border-border pb-3">
              <label className="text-sm text-fg-secondary">
                Métrica
                <select
                  className="ml-2 border rounded px-2 py-1 text-sm"
                  value={metric}
                  onChange={(e) => setMetric(e.target.value as any)}
                >
                  <option value="pass">Precisão de passe (%)</option>
                  <option value="tackle">Êxito em desarmes (%)</option>
                  <option value="rating">Nota média</option>
                  <option value="gfga">Gols feitos × levados</option>
                  <option value="gdiff">Dif. de gols (GF−GA)</option>
                </select>
              </label>

              <div className="flex items-center gap-1.5">
                <span className="text-sm text-fg-secondary">Visual</span>
                {(["line", "area", "bar"] as const).map((k) => (
                  <button
                    key={k}
                    type="button"
                    onClick={() => setChartKind(k)}
                    className={`text-xs px-2.5 py-1 rounded-lg border shadow-sm transition-colors ${
                      chartKind === k ? "bg-accent text-accent-fg border-accent" : "bg-surface text-fg-secondary hover:bg-surface-raised"
                    }`}
                  >
                    {k === "line" ? "Linha" : k === "area" ? "Área" : "Barras"}
                  </button>
                ))}
              </div>

              <label className="text-sm text-fg-secondary">
                Eixo X
                <select
                  className="ml-2 border rounded px-2 py-1 text-sm"
                  value={effectiveXMode}
                  onChange={(e) => setXMode(e.target.value as any)}
                  disabled={clubsWithData.length > 1}
                  title={clubsWithData.length > 1 ? "Com múltiplos clubes, o eixo por Data é desativado." : ""}
                >
                  <option value="index">Jogo #</option>
                  <option value="date">Data</option>
                </select>
              </label>
            </div>

            {/* GRÁFICO PRINCIPAL */}
            <div className="mt-4 h-[360px]">
              <ChartComponent key={resolvedTheme} data={chartData as any} options={baseOptions} />
            </div>

            {/* FAIXA DE RESULTADOS POR CLUBE */}
            <div className="mt-5">
              <div className="text-xs text-fg-muted mb-2">Resultados no período</div>
              <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-3">
                {clubsWithData.map((c) => (
                  <div key={c.clubId} className="border rounded-lg p-2">
                    <div className="text-xs font-medium mb-2">{c.clubName}</div>
                    {c.series.length === 0 ? (
                      <div className="text-sm text-fg-muted">Sem partidas.</div>
                    ) : (
                      <div className="flex gap-1 overflow-x-auto no-scrollbar py-1">
                        {c.series.map((s) => (
                          <span
                            key={`${c.clubId}-${s.matchId}`}
                            title={`${fmtDateBRShort(s.timestamp)} • vs ${s.opponentName} • ${s.goalsFor}-${s.goalsAgainst}`}
                            className={`inline-flex items-center justify-center w-8 h-8 rounded text-white flex-shrink-0 ${pillColor(s.result as Result)}`}
                          >
                            <span className="text-[11px] font-bold leading-none">{s.goalsFor}-{s.goalsAgainst}</span>
                          </span>
                        ))}
                      </div>
                    )}
                  </div>
                ))}
              </div>
            </div>
          </div>

          {/* Top performers (agregado) */}
          <div className="bg-surface border rounded-xl p-4">
            <div className="flex items-center justify-between mb-2">
              <h2 className="font-display font-bold uppercase tracking-wide text-lg text-fg">Top Performers (período)</h2>
              <span className="text-xs text-fg-muted">ordenado por gols ↓</span>
            </div>
            <div className="overflow-x-auto">
              <table className="w-full table-auto text-sm text-center border">
                <thead className="bg-surface-raised">
                  <tr>
                    <th className="p-2 text-left">Jogador</th>
                    <th className="p-2 text-left">Clube</th>
                    <th className="p-2">Partidas</th>
                    <th className="p-2">Gols</th>
                    <th className="p-2">Assistências</th>
                    <th className="p-2">Pré-Assist.</th>
                    <th className="p-2">Partic.</th>
                    <th className="p-2">MOM</th>
                    <th className="p-2">Nota média</th>
                  </tr>
                </thead>
                <tbody>
                  {Object.entries(topsByClub)
                    .flatMap(([cid, arr]) =>
                      (arr ?? []).map((t) => ({
                        ...t,
                        _clubId: Number(cid),
                        _clubName:
                          trendsByClub[Number(cid)]?.clubName ??
                          selectedClubs.find((c) => c.clubId === Number(cid))?.clubName ??
                          `Clube ${cid}`,
                      }))
                    )
                    .sort((a, b) => b.goals - a.goals || b.assists - a.assists || b.avgRating - a.avgRating)
                    .slice(0, 30)
                    .map((t, idx) => {
                      const medal = idx === 0 ? "🥇" : idx === 1 ? "🥈" : idx === 2 ? "🥉" : null;
                      const clr = clubHex(t._clubId);
                      return (
                        <tr
                          key={`${t._clubId}-${t.playerEntityId}`}
                          className="border-t border-l-4"
                          style={{ borderLeftColor: clr }}
                        >
                          <td className="p-2 text-left whitespace-nowrap">
                            {medal && <span className="mr-1">{medal}</span>}
                            {t.playerName}
                          </td>
                          <td className="p-2 text-left whitespace-nowrap">{t._clubName}</td>
                          <td className="p-2">{t.matches}</td>
                          <td className="p-2">{t.goals}</td>
                          <td className="p-2">{t.assists}</td>
                          <td className="p-2">{t.preAssists ?? 0}</td>
                          <td className="p-2 font-medium">{(t.goals ?? 0) + (t.assists ?? 0) + (t.preAssists ?? 0)}</td>
                          <td className="p-2">{t.mom > 0 ? `🏆 ${t.mom}` : t.mom}</td>
                          <td className="p-2"><RatingPill value={Number(t.avgRating)} /></td>
                        </tr>
                      );
                    })}
                </tbody>
              </table>
            </div>
          </div>
        </>
      )}
    </PageShell>
  );
}
